import { readFileSync, unlinkSync } from "node:fs";
import { z } from "zod";
import { chunk } from "../arrayUtils.js";
import { hasCredentials } from "../config.js";
import { createMcpClient } from "../mcpClient.js";
import { positionalArgs } from "../parseArgs.js";
import { REPLAY_ORIGINAL_TRACE_ID_KEYS, REPLAY_TRACE_ID_KEYS, } from "../replayItemIdentity.js";
const BATCH_SIZE = 50;
const CONFIDENCE_LEVELS = [
    "VeryLow",
    "Low",
    "Medium",
    "High",
    "VeryHigh",
];
const lineageFileSchema = z
    .object({
    // The replay test run. Verdicts are keyed by the original-trace lineage, so
    // the server resolves each originalTraceId to its replay trace within this run.
    testRunId: z.uuid(),
    // Canonical; older item files carry the deprecated expectedSourceTraceIds.
    expectedOriginalTraceIds: z.array(z.uuid()).min(1).optional(),
    expectedSourceTraceIds: z.array(z.uuid()).min(1).optional(),
    verdicts: z.array(z.unknown()).min(1),
})
    .refine((d) => d.expectedOriginalTraceIds !== undefined ||
    d.expectedSourceTraceIds !== undefined, {
    message: "lineage file must carry expectedOriginalTraceIds (or the deprecated expectedSourceTraceIds)",
    path: ["expectedOriginalTraceIds"],
});
const directFileSchema = z.object({
    expectedTraceIds: z.array(z.uuid()).min(1),
    verdicts: z.array(z.unknown()).min(1),
});
/**
 * The verdict-entry keys read for each id kind, canonical first. Reuses the
 * shared alias lists so lineage mode accepts `originalTraceId` and its deprecated
 * `sourceTraceId` alias (plus snake_case variants from older item files) and
 * direct mode reads `traceId`. Keeping this in sync with the replay item
 * normalizer means a field rename touches one place.
 */
const ID_KIND_KEYS = {
    originalTraceId: REPLAY_ORIGINAL_TRACE_ID_KEYS,
    traceId: REPLAY_TRACE_ID_KEYS,
};
const ASSERTION_ID_KEYS = ["assertionId", "assertion_id"];
const assertionIdSchema = z.uuid();
function readStringKey(obj, keys) {
    for (const key of keys) {
        const value = obj[key];
        if (typeof value === "string" && value.length > 0) {
            return value;
        }
    }
    return undefined;
}
export function parseVerdict(raw, idKind) {
    if (!raw || typeof raw !== "object") {
        return { error: "verdict entry must be an object" };
    }
    const obj = raw;
    const id = readStringKey(obj, ID_KIND_KEYS[idKind]);
    if (!id) {
        return { error: `verdict entry missing ${idKind}` };
    }
    const assertionId = readStringKey(obj, ASSERTION_ID_KEYS);
    if (assertionId !== undefined &&
        !assertionIdSchema.safeParse(assertionId).success) {
        return {
            error: `verdict for ${id} has an assertionId that is not a UUID: ${assertionId}. Use the id get_trace_assertions prints as [ID: ...], or omit assertionId to record the trace's whole-trace verdict`,
        };
    }
    const scope = assertionId !== undefined ? { assertionId } : {};
    if (obj.skip === true) {
        return { kind: "skip", id, ...scope };
    }
    if (typeof obj.label !== "boolean") {
        return { error: `verdict for ${id} missing boolean label` };
    }
    if (typeof obj.annotation !== "string" || obj.annotation.length === 0) {
        return { error: `verdict for ${id} missing annotation` };
    }
    let confidence;
    if (obj.confidence !== undefined) {
        if (!CONFIDENCE_LEVELS.includes(obj.confidence)) {
            return {
                error: `verdict for ${id} has invalid confidence (expected one of ${CONFIDENCE_LEVELS.join(", ")})`,
            };
        }
        confidence = obj.confidence;
    }
    return {
        kind: "verdict",
        id,
        ...scope,
        label: obj.label,
        annotation: obj.annotation,
        ...(confidence !== undefined && { confidence }),
    };
}
export function findMissingCoverage(expectedIds, verdicts) {
    const seen = new Set(verdicts.map((v) => v.id));
    return expectedIds.filter((id) => !seen.has(id));
}
export function toMcpLabels(verdicts, idKind) {
    const idFields = (id) => idKind === "originalTraceId"
        ? { originalTraceId: id, sourceTraceId: id }
        : { [idKind]: id };
    return verdicts.map((v) => {
        const target = {
            ...idFields(v.id),
            ...(v.assertionId !== undefined && { assertionId: v.assertionId }),
        };
        if (v.kind === "skip") {
            return { ...target, skip: true };
        }
        return {
            ...target,
            label: v.label,
            annotation: v.annotation,
            ...(v.confidence !== undefined && { confidence: v.confidence }),
        };
    });
}
function isInvalidTraceIdResponse(text) {
    return (text.includes("None of the provided trace IDs belong to this organization") ||
        text.includes("Skipped (not in this organization)") ||
        // Current servers say "for original trace(s)"; older servers said
        // "for source trace(s)". Match the common prefix so both are caught.
        text.includes("No replay trace found for"));
}
function expectedLabelState(verdict) {
    if (verdict.kind === "skip") {
        return "skipped";
    }
    return verdict.label ? "PASS" : "FAIL";
}
function expectedAction(verdict) {
    return verdict.kind === "skip" ? "skipped" : "set";
}
const EFFECTIVE_LABEL_LINE_RE = /^- ([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}): ([^;]+); effective (PASS|FAIL|skipped|unlabeled)\b/;
function parseEffectiveLabelLines(mcpText) {
    const parsed = [];
    for (const line of mcpText.split(/\r?\n/)) {
        const match = EFFECTIVE_LABEL_LINE_RE.exec(line.trim());
        if (match) {
            parsed.push({
                id: match[1],
                action: match[2].trim(),
                effective: match[3],
            });
        }
    }
    return parsed;
}
export function parseSaveAgentLabelsResult(mcpText) {
    const states = new Map();
    for (const line of parseEffectiveLabelLines(mcpText)) {
        states.set(line.id, line.effective);
    }
    return states;
}
function groupActionsById(lines) {
    const actions = new Map();
    for (const line of lines) {
        const existing = actions.get(line.id);
        if (existing) {
            existing.push(line.action);
        }
        else {
            actions.set(line.id, [line.action]);
        }
    }
    return actions;
}
function verifyPersistedLabels(opts) {
    const lines = parseEffectiveLabelLines(opts.mcpText);
    const states = parseSaveAgentLabelsResult(opts.mcpText);
    const unclaimedActions = groupActionsById(lines);
    const missingIds = [];
    const mismatchedIds = [];
    for (const verdict of opts.verdicts) {
        const expected = expectedLabelState(verdict);
        if (verdict.assertionId !== undefined) {
            const actions = unclaimedActions.get(verdict.id) ?? [];
            const claimed = actions.indexOf(expectedAction(verdict));
            if (claimed === -1) {
                missingIds.push(verdict.id);
                mismatchedIds.push({ id: verdict.id, expected, actual: "missing" });
            }
            else {
                actions.splice(claimed, 1);
            }
            continue;
        }
        const actual = states.get(verdict.id);
        if (actual === undefined) {
            missingIds.push(verdict.id);
            mismatchedIds.push({ id: verdict.id, expected, actual: "missing" });
        }
        else if (actual !== expected) {
            mismatchedIds.push({ id: verdict.id, expected, actual });
        }
    }
    if (missingIds.length > 0 || mismatchedIds.length > 0) {
        return {
            status: "verification-failed",
            idKind: opts.idKind,
            message: "save_agent_labels returned text, but it did not contain the expected effective label lines.",
            verifiedIds: opts.verifiedIds,
            missingIds,
            mismatchedIds,
        };
    }
    const alreadyVerified = new Set(opts.verifiedIds);
    for (const verdict of opts.verdicts) {
        if (!alreadyVerified.has(verdict.id)) {
            alreadyVerified.add(verdict.id);
            opts.verifiedIds.push(verdict.id);
        }
    }
    return null;
}
/**
 * Pure: pick the input mode (lineage vs direct) and pull out the id kind, the
 * expected coverage list, and the optional testRunId. Returns an error string
 * when the file matches neither shape, preferring the error from whichever
 * shape the file most resembles so the message is actionable.
 */
function resolveInputMode(rawInput) {
    const lineage = lineageFileSchema.safeParse(rawInput);
    if (lineage.success) {
        return {
            idKind: "originalTraceId",
            // Canonical, falling back to the deprecated alias for older item files.
            expectedIds: lineage.data.expectedOriginalTraceIds ??
                lineage.data.expectedSourceTraceIds ??
                [],
            testRunId: lineage.data.testRunId,
            verdicts: lineage.data.verdicts,
        };
    }
    const direct = directFileSchema.safeParse(rawInput);
    if (direct.success) {
        return {
            idKind: "traceId",
            expectedIds: direct.data.expectedTraceIds,
            verdicts: direct.data.verdicts,
        };
    }
    // Neither matched: surface the error from the shape the file looks like.
    const looksLineage = !!rawInput &&
        typeof rawInput === "object" &&
        ("expectedOriginalTraceIds" in rawInput ||
            "expectedSourceTraceIds" in rawInput ||
            "testRunId" in rawInput);
    const chosen = looksLineage ? lineage : direct;
    const message = chosen.success
        ? "input did not match the lineage (testRunId + expectedOriginalTraceIds) or direct (expectedTraceIds) shape"
        : chosen.error.issues
            .map((i) => `${i.path.join(".") || "(root)"}: ${i.message}`)
            .join("; ");
    return { error: message };
}
function collectVerdicts(rawVerdicts, idKind) {
    const verdicts = [];
    const seenTargets = new Set();
    const wholeTraceIds = new Set();
    const assertionScopedIds = new Set();
    for (const raw of rawVerdicts) {
        const parsed = parseVerdict(raw, idKind);
        if ("error" in parsed) {
            return { error: parsed.error };
        }
        const target = `${parsed.id} ${parsed.assertionId ?? ""}`;
        if (seenTargets.has(target)) {
            return {
                error: parsed.assertionId === undefined
                    ? `duplicate verdict for ${idKind} ${parsed.id}: each replay item must have exactly one entry (verdict or skip)`
                    : `duplicate verdict for ${idKind} ${parsed.id} assertion ${parsed.assertionId}: each assertion must have exactly one entry (verdict or skip)`,
            };
        }
        seenTargets.add(target);
        if (parsed.assertionId === undefined) {
            wholeTraceIds.add(parsed.id);
        }
        else {
            assertionScopedIds.add(parsed.id);
        }
        verdicts.push(parsed);
    }
    const contradictory = [...wholeTraceIds].filter((id) => assertionScopedIds.has(id));
    if (contradictory.length > 0) {
        return {
            error: `${idKind} ${contradictory.join(", ")} carries a whole-trace verdict and per-assertion verdicts at once. A trace with assertions gets one entry per assertion and no whole-trace entry, a trace with none gets the single whole-trace entry. The whole-trace verdict is derived from the per-assertion rows, so an entry beside them contradicts the rows it comes from`,
        };
    }
    return verdicts;
}
/**
 * Core orchestration - exposed so tests can drive it with a fake proxy.
 * Validates input, batches the MCP call, verifies each batch persisted, and
 * returns a structured result. Does NOT touch the filesystem; the CLI wrapper
 * handles read/unlink.
 */
export async function persistReplayLabels(opts) {
    const mode = resolveInputMode(opts.rawInput);
    if ("error" in mode) {
        return { status: "invalid-input", message: mode.error };
    }
    const { idKind, expectedIds, testRunId } = mode;
    const collected = collectVerdicts(mode.verdicts, idKind);
    if ("error" in collected) {
        return { status: "invalid-input", message: collected.error };
    }
    const verdicts = collected;
    const missing = findMissingCoverage(expectedIds, verdicts);
    if (missing.length > 0) {
        return {
            status: "missing-coverage",
            idKind,
            missingIds: missing,
            providedIds: [...new Set(verdicts.map((v) => v.id))],
        };
    }
    const persisted = [];
    for (const batch of chunk(verdicts, BATCH_SIZE)) {
        const args = { labels: toMcpLabels(batch, idKind) };
        if (idKind === "originalTraceId" && testRunId !== undefined) {
            args.testRunId = testRunId;
        }
        const result = await opts.client.call("save_agent_labels", args);
        const text = result.content?.[0]?.text ?? "unknown MCP error";
        if (result.isError || isInvalidTraceIdResponse(text)) {
            return {
                status: "mcp-error",
                message: text,
                idKind,
                partialIds: persisted,
            };
        }
        const verificationFailure = verifyPersistedLabels({
            mcpText: text,
            verdicts: batch,
            idKind,
            verifiedIds: persisted,
        });
        if (verificationFailure) {
            return verificationFailure;
        }
    }
    let passCount = 0;
    let failCount = 0;
    let skipCount = 0;
    for (const v of verdicts) {
        if (v.kind === "skip") {
            skipCount += 1;
        }
        else if (v.label) {
            passCount += 1;
        }
        else {
            failCount += 1;
        }
    }
    return {
        status: "ok",
        idKind,
        persistedIds: persisted,
        passCount,
        failCount,
        skipCount,
    };
}
const COMMAND_DESCRIPTION = `Persist replay pass/fail verdicts as agent labels. Prints one JSON result line. On status "ok" the input file is deleted, on any other status it is left in place so the run can be retried.

The file is JSON in one of two shapes, chosen by which expected-ids list it carries.

  Lineage keying (modern replays), keyed by the original trace each item was replayed from:

    {
      "testRunId": "<uuid>",
      "expectedOriginalTraceIds": ["<uuid>", "..."],
      "verdicts": [
        { "originalTraceId": "<uuid>", "label": true, "annotation": "why", "confidence": "High" },
        { "originalTraceId": "<uuid>", "skip": true }
      ]
    }

  Direct keying, keyed by the trace's own id and carrying no testRunId:

    {
      "expectedTraceIds": ["<uuid>", "..."],
      "verdicts": [
        { "traceId": "<uuid>", "label": false, "annotation": "why" }
      ]
    }

Every verdict entry names its trace with the same key its expected-ids list uses ("originalTraceId", its deprecated "sourceTraceId" alias, or "traceId"), and is either a verdict ("label" plus a non-empty "annotation", optionally "confidence" of VeryLow, Low, Medium, High or VeryHigh) or an explicit skip ("skip": true).

An entry may also carry "assertionId", the id of the one assertion that entry scores, as get_trace_assertions prints it under "[ID: ...]". A trace that has assertions gets one entry per assertion, each with its own label and annotation, and no whole-trace entry. A trace with no assertions gets the single whole-trace entry, with no "assertionId". A skip may carry an "assertionId" too, for an assertion whose target could not be resolved on the trace. Sending a whole-trace entry and per-assertion entries for the same trace is rejected, because the whole-trace verdict is derived from the per-assertion rows and an entry beside them contradicts the rows it comes from.

Coverage: every id in the expected-ids list needs at least one entry, either its whole-trace entry or one or more assertion-scoped entries, and a skip counts as covered. This command cannot see which traces have assertions, so it accepts either shape and reports the ids that got neither under "missingIds" with status "missing-coverage".`;
/**
 * CLI entrypoint. Reads `<verdicts.json>`, runs the persist pipeline,
 * prints one JSON line, and exits. On `status: "ok"` the input file is
 * deleted so the next iteration starts clean; on any other status the file
 * is left in place so the agent can retry without losing its work.
 */
export async function runPersistReplayLabels(platform, pluginVersion) {
    const ARGS = [
        {
            name: "verdicts.json",
            format: "path",
            description: "Path to the replay verdicts JSON file to persist, in one of the shapes above.",
        },
    ];
    const path = positionalArgs(ARGS, process.argv, {
        description: COMMAND_DESCRIPTION,
    })[0];
    if (!hasCredentials()) {
        console.error(`Not authenticated. Run ${platform.loginHint} first.`);
        process.exit(1);
    }
    let raw;
    try {
        raw = JSON.parse(readFileSync(path, "utf-8"));
    }
    catch (err) {
        const message = err instanceof Error ? err.message : String(err);
        console.log(JSON.stringify({
            status: "invalid-input",
            message: `Failed to read or parse ${path}: ${message}`,
            path,
        }));
        process.exit(1);
    }
    const result = await persistReplayLabels({
        client: createMcpClient(platform, pluginVersion),
        rawInput: raw,
    });
    if (result.status === "ok") {
        try {
            unlinkSync(path);
        }
        catch {
            // Best-effort cleanup. Failure to unlink is not a script failure -
            // the labels persisted, which is what callers care about.
        }
        console.log(JSON.stringify({ ...result, path }));
        process.exit(0);
    }
    console.log(JSON.stringify({ ...result, path }));
    process.exit(1);
}
